create or replace TABLE BIAID_TOOLS_PROJECTS_PRODUCTION.FE_MSTR_TIMESHEETS.T_TIMESHEET_ENTRY (
	DWH_TIMESHEET_ENTRY_UUID VARCHAR(40) NOT NULL COMMENT 'Universally unique identifier - identifying the timesheet entry row. Can be used for exports and reimports of editted version of a row, without exposing the PK',
	TIMESHEET_SID NUMBER(38,0) NOT NULL COMMENT 'Artificially Generated | Unique identifier of the timesheet. All entries within a single timesheet have the same timesheet_sid value',
	PSP_ELEMENT_CD VARCHAR(50) NOT NULL COMMENT 'SrcFile.PSP-Element | Code of the PSP element to which the efforts are booked',
	PROJECT_TASK_CD VARCHAR(50) NOT NULL COMMENT 'SrcFile.ID-Nummer | Code of the task/work package to which the efforts are booked',
	TASK_SUBJECT VARCHAR(255) COMMENT 'SrcFile.Benennung | Name/Subject of the task/work package to which the efforts are booked',
	BS_ITS_CD VARCHAR(50) COMMENT 'SrcFile.Log_BS_ITS |  Code of the business/IT solution',
	LEER1 VARCHAR(255) COMMENT 'empty. reserved for future use',
	LEER2 VARCHAR(255) COMMENT 'empty. reserved for future use',
	TIMESHEET_ENTRY_DT DATE NOT NULL COMMENT 'SrcFile.Datum | Date for which the efforts are booked (when the actual work was done)',
	WORK_DURATION_HOURS NUMBER(38,5) NOT NULL COMMENT 'SrcFile.Stunden | Duration of the booked efforts in hours ( 1.50 means 90 mins)',
	WORK_LOCATION_CD VARCHAR(50) NOT NULL COMMENT 'SrcFile.Onsite/Ofsite | Value indicating if the work was done onsite or offsite',
	EXTERNAL_EMPLOYEE_COMMENT_TXT VARCHAR(1000) COMMENT 'SrcFile.Tätigkeitsbeschreibung |  Notes from the external employee attached to the effort booking',
	DEPARTMENT_NAME VARCHAR(50) COMMENT 'SrcFile.Abteilung | Department for which this external employee works',
	TEAM_NAME VARCHAR(50) COMMENT 'SrcFile.Team | Team for which this external employee works',
	QUOTA_ORDER_NR VARCHAR(50) COMMENT 'MISSING - should be in SrcFile.Bestellung | Number of the quota order for manpower',
	EXTERNAL_EMPLOYEE_FULL_NAME VARCHAR(100) NOT NULL COMMENT 'SrcFile.Name | Full name of the external employee',
	EXTERNAL_SUPPLIER_NAME VARCHAR(100) NOT NULL COMMENT 'SrcFile.Log_DL | name of the company that provides external employees',
	TIMESHEET_ENTRY_STATUS VARCHAR(25) COMMENT 'Set from MSTR/AbIntiio | Status of the timesheet entry (submitted, approved, rejected, exported, corrected)',
	INTENDED_APPROVER_NAME VARCHAR(100) COMMENT 'MISSING - should be in SrcFile | Name of the solution expert who should (approve/reject) the timesheet entry',
	ACTUAL_APPROVER_NAME VARCHAR(100) COMMENT 'Set from MSTR | Name of the solution expert who actually approved/rejected the timesheet entry',
	ACTUAL_APPROVER_COMMENT_TXT VARCHAR(500) COMMENT 'Set from MSTR | Comments set by solution expert (usually when rejecting a record)',
	DWH_CREATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'System Filed | Point in time when this row was created in the database',
	DWH_UPDATED_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'System Filed | Point in time of the last update of this record',
	DWH_SRC_FILE_NAME VARCHAR(500) NOT NULL COMMENT 'System Filed | Name of the source file from which this record is imported',
	SRC_FILE_TMSP TIMESTAMP_LTZ(9) NOT NULL COMMENT 'System Filed | timestamp (date created) of the source file for this record.',
	constraint PK_T_TIMESHEET_ENTRY primary key (DWH_TIMESHEET_ENTRY_UUID)
)COMMENT='Table contains one row per every time sheet records (entry) booked on a project in Schwarz Group'
;